LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA = CONVERT(@m4_static USING utf8) AND CONVERT(c.TABLE_NAME USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT('spawnlist_npc' USING utf8mb4) COLLATE utf8mb4_general_ci AND CONVERT(c.COLUMN_NAME USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.col USING utf8mb4) COLLATE utf8mb4_general_ci
