LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA = CONVERT(@m4_static USING utf8) AND CONVERT(c.TABLE_NAME USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT('角色_力量成長' USING utf8mb4) COLLATE utf8mb4_general_ci AND CONVERT(c.COLUMN_NAME USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.col USING utf8mb4) COLLATE utf8mb4_general_ci
WHERE (x.col = '' AND @m4_te = 0) OR (x.col <> '' AND @m4_te = 1 AND c.COLUMN_NAME IS NULL);
SET @m4_te = (SELECT COUNT(*) FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA = CONVERT(@m4_static USING utf8) AND CONVERT(t.TABLE_NAME USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT('角色_敏捷成長' USING utf8mb4) COLLATE utf8mb4_general_ci);
