-- ===== V3：引擎（SettlementSql.check 要求收據表 InnoDB；SharedDatabase.check 要求 character_lito 是 InnoDB 或 MyISAM）=====
SELECT 'V3' AS check_id, w.schema_name, w.tbl, IFNULL(t.ENGINE, '（缺表）') AS engine,
       IF(t.ENGINE IS NOT NULL AND FIND_IN_SET(UPPER(t.ENGINE), w.allowed) > 0, 'PASS',
          IF((@m4_fail := @m4_fail + 1) > 0, 'FAIL', 'FAIL')) AS status
FROM (SELECT @m4_lito AS schema_name, 'lito_battle_settlement' AS tbl, 'INNODB' AS allowed
      UNION ALL SELECT @m4_ac, 'character_lito', 'INNODB,MYISAM') w
LEFT JOIN information_schema.TABLES t
  ON CONVERT(t.TABLE_SCHEMA USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(w.schema_name USING utf8mb4) COLLATE utf8mb4_general_ci
 AND CONVERT(t.TABLE_NAME USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(w.tbl USING utf8mb4) COLLATE utf8mb4_general_ci;

-- ===== V4：精簡資源表剛好 10 張（ResourceDatabase.load），且 release_id=1 的 qualified_version＝0.6.61 =====
SET @m4_res = (SELECT COUNT(*) FROM information_schema.TABLES
               WHERE TABLE_SCHEMA = CONVERT(@m4_lito USING utf8) AND LEFT(TABLE_NAME, 14) = 'lito_resource_');
SET @m4_res_ok = (SELECT COUNT(*) FROM information_schema.TABLES
               WHERE TABLE_SCHEMA = CONVERT(@m4_lito USING utf8)
                 AND TABLE_NAME IN ('lito_resource_skill_value','lito_resource_buff','lito_resource_projectile','lito_resource_map',
                                    'lito_resource_zone','lito_resource_portal','lito_resource_npc_identity','lito_resource_map_page',
                                    'lito_resource_release','lito_resource_pending'));
SELECT 'V4a' AS check_id, @m4_res AS lito_resource_tables, @m4_res_ok AS expected_names_found,
       IF(@m4_res = 10 AND @m4_res_ok = 10, 'PASS', IF((@m4_fail := @m4_fail + 1) > 0, 'FAIL', 'FAIL')) AS status;
SET @m4_has = (SELECT COUNT(*) FROM information_schema.COLUMNS
               WHERE TABLE_SCHEMA = CONVERT(@m4_lito USING utf8) AND TABLE_NAME = 'lito_resource_release' AND COLUMN_NAME = 'qualified_version');
SET @m4_release = NULL;
SET @m4_sql = IF(@m4_has = 1, CONCAT('SELECT qualified_version INTO @m4_release FROM `', @m4_lito, '`.`lito_resource_release` WHERE release_id = 1'), 'DO 0');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;
SELECT 'V4b' AS check_id, IFNULL(@m4_release, '（讀不到）') AS qualified_version,
       IF(IFNULL(@m4_release, '') = '0.6.61', 'PASS', IF((@m4_fail := @m4_fail + 1) > 0, 'FAIL', 'FAIL')) AS status;

-- V4c：lito_room_policy 有 policy_id=1 的一列（NativeRoomRules.install 啟動時讀，NativeRoomRules.java:20-24）
SET @m4_has = (SELECT COUNT(*) FROM information_schema.COLUMNS
               WHERE TABLE_SCHEMA = CONVERT(@m4_lito USING utf8) AND TABLE_NAME = 'lito_room_policy' AND COLUMN_NAME = 'policy_id');
SET @m4_policy = -1;
SET @m4_sql = IF(@m4_has = 1, CONCAT('SELECT COUNT(*) INTO @m4_policy FROM `', @m4_lito, '`.`lito_room_policy` WHERE policy_id = 1'), 'DO 0');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;
SELECT 'V4c' AS check_id, @m4_policy AS room_policy_rows_with_id_1,
       IF(@m4_policy = 1, 'PASS', IF((@m4_fail := @m4_fail + 1) > 0, 'FAIL', 'FAIL')) AS status;

-- ===== V5：來源路由只有一條啟用，且指向實驗角色庫（#83；UnifiedConfiguration 讀 lito_source_server）=====
SET @m4_has = (SELECT COUNT(*) FROM information_schema.TABLES
               WHERE TABLE_SCHEMA = CONVERT(@m4_lito USING utf8) AND TABLE_NAME = 'lito_source_server');
SET @m4_sql = IF(@m4_has = 1, CONCAT('SELECT ''V5'' AS check_id, source_id, display_name, character_database, enabled, 42083 + source_id AS expected_game_port FROM `',
                                    @m4_lito, '`.`lito_source_server` ORDER BY source_id'), 'SELECT ''V5'' AS check_id, ''lito_source_server 不存在'' AS note');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;
SET @m4_routes = -1; SET @m4_routes_ok = -1;
SET @m4_sql = IF(@m4_has = 1, CONCAT('SELECT IFNULL(SUM(enabled <> 0), 0), IFNULL(SUM(enabled <> 0 AND character_database = CONVERT(@m4_ac USING utf8mb4) COLLATE utf8mb4_general_ci), 0) INTO @m4_routes, @m4_routes_ok FROM `',
                                    @m4_lito, '`.`lito_source_server`'), 'DO 0');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;
SELECT 'V5' AS check_id, @m4_routes AS enabled_routes, @m4_routes_ok AS enabled_routes_to_experiment_db,
       IF(@m4_routes = 1 AND @m4_routes_ok = 1, 'PASS', IF((@m4_fail := @m4_fail + 1) > 0, 'FAIL', 'FAIL')) AS status;

-- ===== V6：LiTo GM 指令列（.polyme／.move／.loc／.item／.spawn／.de；缺少只影響 GM 步驟，列 WARN）=====
SET @m4_has = (SELECT COUNT(*) FROM information_schema.TABLES
               WHERE TABLE_SCHEMA = CONVERT(@m4_lito USING utf8) AND TABLE_NAME = 'commands');
SET @m4_sql = IF(@m4_has = 1, CONCAT(
  'SELECT ''V6'' AS check_id, w.name, IFNULL(c.class_name, ''（缺）'') AS class_name, c.access_level, ',
  'IF(c.name IS NULL, IF((@m4_warn := @m4_warn + 1) > 0, ''WARN'', ''WARN''), ''PASS'') AS status ',
  'FROM (SELECT ''polyme'' AS name UNION ALL SELECT ''move'' UNION ALL SELECT ''loc'' UNION ALL SELECT ''item'' UNION ALL SELECT ''spawn'' UNION ALL SELECT ''de'') w ',
  'LEFT JOIN `', @m4_lito, '`.`commands` c ON CONVERT(c.name USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(w.name USING utf8mb4) COLLATE utf8mb4_general_ci'),
  'SELECT ''V6'' AS check_id, ''commands 不存在'' AS note');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;

