  ) r
  JOIN (SELECT 'SELECT' AS priv UNION ALL SELECT 'INSERT' UNION ALL SELECT 'UPDATE') p
    ON FIND_IN_SET(p.priv, REPLACE(r.privs, '/', ',')) > 0
) x
WHERE NOT EXISTS (SELECT 1 FROM information_schema.TABLE_PRIVILEGES tp
                  WHERE CONVERT(tp.GRANTEE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(@m4_grantee USING utf8mb4) COLLATE utf8mb4_general_ci
                    AND CONVERT(tp.TABLE_SCHEMA USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.schema_name USING utf8mb4) COLLATE utf8mb4_general_ci
                    AND CONVERT(tp.TABLE_NAME USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.tbl USING utf8mb4) COLLATE utf8mb4_general_ci
                    AND CONVERT(tp.PRIVILEGE_TYPE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.priv USING utf8mb4) COLLATE utf8mb4_general_ci)
  AND NOT EXISTS (SELECT 1 FROM information_schema.SCHEMA_PRIVILEGES sp
                  WHERE CONVERT(sp.GRANTEE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(@m4_grantee USING utf8mb4) COLLATE utf8mb4_general_ci
                    AND CONVERT(sp.TABLE_SCHEMA USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.schema_name USING utf8mb4) COLLATE utf8mb4_general_ci
                    AND CONVERT(sp.PRIVILEGE_TYPE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.priv USING utf8mb4) COLLATE utf8mb4_general_ci)
  AND NOT EXISTS (SELECT 1 FROM information_schema.USER_PRIVILEGES up
                  WHERE CONVERT(up.GRANTEE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(@m4_grantee USING utf8mb4) COLLATE utf8mb4_general_ci
                    AND CONVERT(up.PRIVILEGE_TYPE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(x.priv USING utf8mb4) COLLATE utf8mb4_general_ci)
ORDER BY x.grp, x.tbl, x.priv;

-- V7b：實驗帳號在三個實驗 schema「以外」看得到的授權（預期 0 列；有列＝越界，WARN，交主控判斷，不要自己撤權）
SELECT 'V7b' AS check_id, w.scope, w.TABLE_SCHEMA, w.TABLE_NAME, w.PRIVILEGE_TYPE,
       IF((@m4_warn := @m4_warn + 1) > 0, 'WARN', 'WARN') AS status
FROM (
  SELECT 'schema' AS scope, GRANTEE, TABLE_SCHEMA, '*' AS TABLE_NAME, PRIVILEGE_TYPE FROM information_schema.SCHEMA_PRIVILEGES
  UNION ALL
  SELECT 'table', GRANTEE, TABLE_SCHEMA, TABLE_NAME, PRIVILEGE_TYPE FROM information_schema.TABLE_PRIVILEGES
  UNION ALL
  SELECT 'global', GRANTEE, '*', '*', PRIVILEGE_TYPE FROM information_schema.USER_PRIVILEGES WHERE PRIVILEGE_TYPE <> 'USAGE'
) w
WHERE CONVERT(w.GRANTEE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(@m4_grantee USING utf8mb4) COLLATE utf8mb4_general_ci
  AND CONVERT(w.TABLE_SCHEMA USING utf8mb4) COLLATE utf8mb4_general_ci NOT REGEXP '_lito_exp$'
ORDER BY w.scope, w.TABLE_SCHEMA, w.TABLE_NAME, w.PRIVILEGE_TYPE;

-- V7c：實驗帳號的寫入權限（預期只有 character_lito 與 lito_battle_settlement 的 INSERT／UPDATE；其他列 WARN）
SELECT 'V7c' AS check_id, w.scope, w.TABLE_SCHEMA, w.TABLE_NAME, w.PRIVILEGE_TYPE,
       IF(w.scope = 'table' AND w.PRIVILEGE_TYPE IN ('INSERT', 'UPDATE')
          AND ((CONVERT(w.TABLE_SCHEMA USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(@m4_ac USING utf8mb4) COLLATE utf8mb4_general_ci AND w.TABLE_NAME = 'character_lito')
            OR (CONVERT(w.TABLE_SCHEMA USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(@m4_lito USING utf8mb4) COLLATE utf8mb4_general_ci AND w.TABLE_NAME = 'lito_battle_settlement')),
          'PASS', IF((@m4_warn := @m4_warn + 1) > 0, 'WARN', 'WARN')) AS status
FROM (
  SELECT 'schema' AS scope, GRANTEE, TABLE_SCHEMA, '*' AS TABLE_NAME, PRIVILEGE_TYPE FROM information_schema.SCHEMA_PRIVILEGES
  UNION ALL
  SELECT 'table', GRANTEE, TABLE_SCHEMA, TABLE_NAME, PRIVILEGE_TYPE FROM information_schema.TABLE_PRIVILEGES
) w
WHERE CONVERT(w.GRANTEE USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(@m4_grantee USING utf8mb4) COLLATE utf8mb4_general_ci
  AND w.PRIVILEGE_TYPE <> 'SELECT'
ORDER BY w.scope, w.TABLE_SCHEMA, w.TABLE_NAME, w.PRIVILEGE_TYPE;

-- ===== V8：戰績與收據基線（只列筆數；逐列前後對照用 m4-sql-snapshot.ps1）=====
SET @m4_has = (SELECT COUNT(*) FROM information_schema.TABLES
               WHERE (TABLE_SCHEMA = CONVERT(@m4_ac USING utf8) AND TABLE_NAME IN ('character_lito', 'characters', 'accounts'))
                  OR (TABLE_SCHEMA = CONVERT(@m4_lito USING utf8) AND TABLE_NAME = 'lito_battle_settlement'));
SET @m4_sql = IF(@m4_has = 4, CONCAT(
  'SELECT ''V8'' AS check_id, ',
  '(SELECT COUNT(*) FROM `', @m4_ac, '`.`accounts`) AS accounts, ',
  '(SELECT COUNT(*) FROM `', @m4_ac, '`.`characters`) AS characters, ',
  '(SELECT COUNT(*) FROM `', @m4_ac, '`.`character_lito`) AS character_lito, ',
  '(SELECT COUNT(*) FROM `', @m4_lito, '`.`lito_battle_settlement`) AS receipts, ',
  '(SELECT COUNT(*) FROM `', @m4_lito, '`.`lito_battle_settlement` WHERE applied = 0) AS receipts_pending, ',
  '(SELECT COUNT(*) FROM `', @m4_lito, '`.`lito_battle_settlement` WHERE source_database = CONVERT(@m4_ac USING utf8mb4) COLLATE utf8mb4_general_ci AND applied = 0) AS receipts_pending_this_source'),
  'SELECT ''V8'' AS check_id, ''accounts／characters／character_lito／lito_battle_settlement 有缺表，見 V2'' AS note');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;

-- ===== V9：資料前置狀態（INFO，不計入 verdict；對應 M4-RUNBOOK「資料前置」D1–D14。characters_below_level_15 以外，數字是 0 的項目
--        代表對應的驗收步驟會被資料擋住，執行 m4-seed-exp.sql 補）=====
SET @m4_has = (SELECT COUNT(*) FROM information_schema.TABLES
               WHERE (TABLE_SCHEMA = CONVERT(@m4_ac USING utf8) AND TABLE_NAME IN ('accounts', 'characters', 'character_items', 'character_skills'))
                  OR (TABLE_SCHEMA = CONVERT(@m4_static USING utf8) AND TABLE_NAME = 'etcitem'));
SET @m4_sql = IF(@m4_has = 5, CONCAT(
  'SELECT ''V9'' AS check_id, ',
  '(SELECT COUNT(*) FROM `', @m4_ac, '`.`accounts` WHERE access_level >= 200 AND banned = 0) AS gm_accounts_level_200, ',
  '(SELECT IFNULL(MAX(q.n), 0) FROM (SELECT COUNT(*) AS n FROM `', @m4_ac, '`.`characters` WHERE Banned = 0 GROUP BY account_name) q) AS max_characters_per_account, ',
  '(SELECT COUNT(*) FROM `', @m4_ac, '`.`characters` WHERE level < 15 AND Banned = 0) AS characters_below_level_15, ',
  '(SELECT COUNT(DISTINCT account_name) FROM `', @m4_ac, '`.`characters` WHERE Banned = 0) AS accounts_with_characters, ',
  '(SELECT COUNT(*) FROM (SELECT Clanname FROM `', @m4_ac, '`.`characters` WHERE Banned = 0 AND Clanname <> '''' GROUP BY Clanname HAVING COUNT(DISTINCT account_name) >= 2) q2) AS clans_spanning_two_accounts, ',
  '(SELECT COUNT(*) FROM `', @m4_ac, '`.`characters` WHERE Type = 5 AND Banned = 0) AS dragon_knights, ',
  '(SELECT COUNT(*) FROM `', @m4_ac, '`.`characters` WHERE Type = 6 AND Banned = 0) AS illusionists, ',
  '(SELECT COUNT(DISTINCT char_obj_id) FROM `', @m4_ac, '`.`character_skills` WHERE skill_id = 4) AS characters_with_skill_4, ',
  '(SELECT COUNT(DISTINCT char_obj_id) FROM `', @m4_ac, '`.`character_skills` WHERE skill_id = 26) AS characters_with_skill_26, ',
  '(SELECT COUNT(DISTINCT char_obj_id) FROM `', @m4_ac, '`.`character_skills` WHERE skill_id = 29) AS characters_with_skill_29, ',
  '(SELECT COUNT(DISTINCT char_obj_id) FROM `', @m4_ac, '`.`character_skills` WHERE skill_id = 186) AS characters_with_skill_186, ',
  '(SELECT COUNT(DISTINCT char_id) FROM `', @m4_ac, '`.`character_items` WHERE item_id = 40015) AS characters_with_blue_potion, ',
  '(SELECT COUNT(DISTINCT char_id) FROM `', @m4_ac, '`.`character_items` WHERE item_id = 55000) AS characters_with_magic_doll_55000, ',
  '(SELECT COUNT(DISTINCT i.char_id) FROM `', @m4_ac, '`.`character_items` i JOIN `', @m4_static, '`.`etcitem` e ON e.item_id = i.item_id ',
  'WHERE e.classname = ''wand.Storm_Walk'') AS characters_with_gm_wand'),
  'SELECT ''V9'' AS check_id, ''accounts／characters／character_items／character_skills／etcitem 有缺表，見 V2'' AS note');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;
-- V9b：擂台商店是否有藍色藥水 40015、變形卷軸 40088（D14；TournamentShopCatalog 讀 lito_tournament_shop）
SET @m4_has = (SELECT COUNT(*) FROM information_schema.COLUMNS
               WHERE TABLE_SCHEMA = CONVERT(@m4_lito USING utf8) AND TABLE_NAME = 'lito_tournament_shop' AND COLUMN_NAME IN ('item_id', 'enabled', 'buy_price'));
SET @m4_sql = IF(@m4_has = 3, CONCAT('SELECT ''V9b'' AS check_id, w.item_id, IFNULL(s.enabled, ''（缺）'') AS enabled, s.buy_price ',
  'FROM (SELECT 40015 AS item_id UNION ALL SELECT 40088) w LEFT JOIN `', @m4_lito, '`.`lito_tournament_shop` s ON s.item_id = w.item_id'),
  'SELECT ''V9b'' AS check_id, ''lito_tournament_shop 不存在或欄位不同，見 V2'' AS note');
PREPARE m4_stmt FROM @m4_sql; EXECUTE m4_stmt; DEALLOCATE PREPARE m4_stmt;

-- ===== 結論 =====
SELECT IF(@m4_fail = 0, 'M4-VERIFY: PASS', 'M4-VERIFY: FAIL') AS verdict, @m4_fail AS blocking_findings, @m4_warn AS warnings,
       @m4_static AS static_schema, @m4_lito AS lito_schema, @m4_ac AS character_schema, @m4_grantee AS grantee;
